﻿/* Cyber Minesweeper Arcade App Icon & Modal Styles */
.minesweeper-app-icon-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  background: transparent;
  border: none;
  padding: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
  pointer-events: auto;
  width: 100%;
}

.minesweeper-app-icon-card:hover {
  border: none;
  transform: translateY(-3px);
  box-shadow: none;
}

.minesweeper-app-icon {
  width: 72px;
  height: 72px;
  background: var(--ink);
  border: 1px solid var(--cyan);
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--cyan) 15%, transparent);
  position: relative;
  pointer-events: none;
}

.minesweeper-icon-canvas {
  width: 56px;
  height: 56px;
  display: block;
  pointer-events: none;
}

.minesweeper-icon-label {
  font-family: var(--display);
  font-size: 16px;
  color: var(--paper);
  margin: 0;
  pointer-events: none;
}

/* Modal Overlay */
.minesweeper-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(9, 11, 10, 0.85);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 12px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.minesweeper-modal-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

.minesweeper-modal-container {
  background: var(--panel);
  border: 1px solid var(--cyan);
  width: 100%;
  max-width: 480px;
  max-height: 96vh;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 15px color-mix(in srgb, var(--cyan) 10%, transparent);
  box-sizing: border-box;
}

.minesweeper-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 6px;
}

.minesweeper-title {
  font-family: var(--display);
  font-size: 15px;
  color: var(--paper);
  margin: 0;
  letter-spacing: 0.05em;
}

